A = (-1/2,1/4);
B = (1/2,1/4);
C = (0,-1/4);
D = (1/2,-1/4);
F = (0,1/4);
V = (0,0);

draw(graph(func,-0.8,0.8));
draw((-0.8,-1/4)--(0.8,-1/4),dashed);
draw(A--B--D);
draw(A--V--B);
draw(C--F);

label("$\ell$", (0.8,-1/4), E);

dot("$A$", A, SW);
dot("$B$", B, SE);
dot("$C$", C, S);
dot("$D$", D, S);
dot("$F$", F, N);
dot("$V$", V, SW);
